(7096147, 1080889, 30861, '<td valign="top">Fascinating phenomenon. I''ve seen this at sea but never noticed it on land.</td>', 'Fascinating phenomenon. I''ve seen this at sea but never noticed it on land.', '2013-09-01 01:10:19.000000', NULL, 1),
(7096152, 1081698, 30861, '<td valign="top">Gawd, the things he puts up with... :-)</td>', 'Gawd, the things he puts up with... :-)', '2013-09-01 01:11:13.000000', NULL, 1),
(7096183, 1080442, 60173, '<td valign="top">I really like this. The streaks make the other side of the window look like a painting. Great clouds too. <br/> <br/>I''m not totally sold on the composition, but I can''t offer a better suggestion.</td>', 'I really like this. The streaks make the other side of the window look like a painting. Great clouds too.  I''m not totally sold on the composition, but I can''t offer a better suggestion.', '2013-09-01 01:27:11.000000', NULL, 1),
(7096193, 1081521, 60173, '<td valign="top">There''s a couple really happy people in that crowd. Did they just start? :)<br/> <br/>I''m not really getting "rain" out of this, but judging by the available overcast light, I do believe it. The guy on the far right looks a little damp, but it''s hard to tell with the others because of hats or lack of visible hair.</td>', 'There''s a couple really happy people in that crowd. Did they just start? :) I''m not really getting "rain" out of this, but judging by the available overcast light, I do believe it. The guy on the far right looks a little damp, but it''s hard to tell with the others because of hats or lack of visible hair.', '2013-09-01 01:31:00.000000', NULL, 1),
(7096197, 1077979, 104230, '<td valign="top">Yes, I am transported there. Love the textures and colors, and the sense of movement.</td>', 'Yes, I am transported there. Love the textures and colors, and the sense of movement.', '2013-09-01 01:35:31.000000', NULL, 1),
